def apply(ctx) -> None:
    """Paint the terrain array from the run-length table."""
    terrain = ctx.mm.terrain
    index = 0
    for count, terrain_id, elevation, layer in RUNS:
        for _ in range(count):
            tile = terrain[index]
            tile.terrain_id = terrain_id
            tile.elevation = elevation
            tile.layer = layer
            index += 1
